// sandboxExpectations is internal/request/testdata/sandbox-expectations.json,
// generated by js/sandbox/expectations.mjs with Node and the exact npm
// versions in js/sandbox/package-lock.json. The expressions are run again
// through the embedded bundles here, so a library behaviour change or a
// bundling mistake shows up as a difference from Node.
type sandboxExpectations struct {
	Modules map[string]struct {
		Prelude   string `json:"prelude"`
		GoPrelude string `json:"goPrelude"`
		Cases     []struct {
			Name string `json:"name"`
			Expr string `json:"expr"`
			Want string `json:"want"`
		} `json:"cases"`
	} `json:"modules"`
}

func TestSandboxLibrariesMatchNode(t *testing.T) {
	data, err := os.ReadFile(filepath.Join("testdata", "sandbox-expectations.json"))
	if err != nil {
		t.Fatal(err)
	}
	var doc sandboxExpectations
	if err := json.Unmarshal(data, &doc); err != nil {
		t.Fatal(err)
	}
	names := make([]string, 0, len(doc.Modules))
	for name := range doc.Modules {
		names = append(names, name)
	}
	slices.Sort(names)
	for _, name := range names {
		module := doc.Modules[name]
		t.Run(name, func(t *testing.T) {
			prelude := module.GoPrelude
			if prelude == "" {
				prelude = module.Prelude
			}
			var script strings.Builder
			script.WriteString(prelude)
			script.WriteString("\nconst __out = [];\n")
			for _, c := range module.Cases {
				fmt.Fprintf(&script, "__out.push(JSON.stringify(%s));\n", c.Expr)
			}
			script.WriteString(`pm.environment.set("out", JSON.stringify(__out));`)
			run := &scriptRun{vars: map[string]string{}}
			if err := runScript(script.String(), run, nil); err != nil {
				t.Fatalf("%s: %v", name, err)
			}
			var got []string
			if err := json.Unmarshal([]byte(run.vars["out"]), &got); err != nil {
				t.Fatalf("%s: results %q: %v", name, run.vars["out"], err)
			}
			if len(got) != len(module.Cases) {
				t.Fatalf("%s: %d results, want %d", name, len(got), len(module.Cases))
			}
			for i, c := range module.Cases {
				if got[i] != c.Want {
					t.Errorf("%s: %s = %s, want %s (Node)", name, c.Name, got[i], c.Want)
				}
			}
		})
	}
}

// TestSandboxGlobals covers the globals Postman's legacy sandbox adds on top
// of require. The expected strings come from Node with lodash 4.18.1,
// crypto-js 4.2.0 and cheerio 0.22.0.
func TestSandboxGlobals(t *testing.T) {
	script := `
const out = {};
out.buffer = Buffer.from("hi").toString("base64");
out.atob = atob("aGk=");
out.btoa = btoa("hi");
out.atobRequire = require("atob")("aGk=");
out.btoaRequire = require("btoa")("hi");
out.xml = xml2Json("<a><b>1</b></a>");
out.lodash = _.kebabCase("Hello World");
out.crypto = CryptoJS.SHA256("x").toString().slice(0, 8);
out.cheerio = cheerio.load("<title>T</title>")("title").text();
pm.environment.set("out", JSON.stringify(out));`
	run := &scriptRun{vars: map[string]string{}}
	if err := runScript(script, run, nil); err != nil {
		t.Fatal(err)
	}
	var got map[string]any
	if err := json.Unmarshal([]byte(run.vars["out"]), &got); err != nil {
		t.Fatal(err)
	}
	want := map[string]any{
		"buffer": "aGk=", "atob": "hi", "btoa": "aGk=", "atobRequire": "hi", "btoaRequire": "aGk=",
		"xml":    map[string]any{"a": map[string]any{"b": "1"}},
		"lodash": "hello-world", "crypto": "2d711642", "cheerio": "T",
	}
	for key, value := range want {
		if fmt.Sprint(got[key]) != fmt.Sprint(value) {
			t.Errorf("%s = %v, want %v", key, got[key], value)
		}
	}
}

// TestSandboxTimers covers the script-scoped timer queue: due order, clearing,
// intervals, awaiting a timer and tests recorded from a callback. Delays are
// virtual and never sleep.
func TestSandboxTimers(t *testing.T) {
	cases := []struct {
		name, script, want string
	}{
		{"due order", `const out = []; const save = () => pm.environment.set("out", out.join(",")); setTimeout(() => { out.push(30); save(); }, 30); setTimeout(() => { out.push(10); save(); }, 10); setTimeout(() => { out.push(20); save(); }, 20);`, "10,20,30"},
		{"same delay is fifo", `const out = []; const save = () => pm.environment.set("out", out.join(",")); setTimeout(() => { out.push(1); save(); }, 0); setTimeout(() => { out.push(2); save(); }, 0);`, "1,2"},
		{"clear timeout", `const out = []; const a = setTimeout(() => { out.push("a"); pm.environment.set("out", out.join(",")); }, 1); setTimeout(() => { out.push("b"); pm.environment.set("out", out.join(",")); }, 2); clearTimeout(a);`, "b"},
		{"clear interval", `const out = []; let n = 0; const id = setInterval(() => { out.push(++n); pm.environment.set("out", out.join(",")); if (n === 3) clearInterval(id); }, 1);`, "1,2,3"},
		{"immediate", `setImmediate((a, b) => { pm.environment.set("out", a + b); }, "x", "y");`, "xy"},
		{"callback schedules", `const out = []; const save = () => pm.environment.set("out", out.join(",")); setTimeout(() => { out.push(1); save(); setTimeout(() => { out.push(2); save(); }, 0); }, 0);`, "1,2"},
		{"await timer", `await new Promise((resolve) => setTimeout(resolve, 5)); pm.environment.set("out", "ok");`, "ok"},
		{"timer error", `setTimeout(() => { throw new Error("boom"); }, 0);`, "boom"},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			run := &scriptRun{vars: map[string]string{}}
			err := runScript(c.script, run, nil)
			if c.name == "timer error" {
				if err == nil || !strings.Contains(err.Error(), c.want) {
					t.Fatalf("err = %v, want one containing %q", err, c.want)
				}
				return
			}
			if err != nil {
				t.Fatal(err)
			}
			if run.vars["out"] != c.want {
				t.Errorf("out = %q, want %q", run.vars["out"], c.want)
			}
		})
	}
	// A test recorded from a timer is reported, because timers run before
	// finish collects pm.test.
	run := &scriptRun{vars: map[string]string{}}
	if err := runScript(`setTimeout(() => pm.test("from timer", () => true), 0);`, run, nil); err != nil {
		t.Fatal(err)
	}
	if len(run.tests) != 1 || run.tests[0].Name != "from timer" || !run.tests[0].Pass {
		t.Fatalf("tests = %+v", run.tests)
	}
}

// TestSandboxHostileInputStaysBounded parses large and entity-heavy input
// with each library that takes untrusted bodies. Every case is its own script,
// so the normal two-second budget is the bound; a hang fails the test instead
// of stalling the app.
func TestSandboxHostileInputStaysBounded(t *testing.T) {
	t.Run("cheerio", func(t *testing.T) {
		run := &scriptRun{vars: map[string]string{}}
		err := runScript(`
const cheerio = require("cheerio");
const parts = [];
for (let i = 0; i < 500; i++) parts.push("<div class='row'><span>value " + i + "</span></div>");
const $ = cheerio.load(parts.join(""));
pm.environment.set("out", String($(".row").length));`, run, nil)
		if err != nil {
			t.Fatal(err)
		}
		if run.vars["out"] != "500" {
			t.Errorf("rows = %s, want 500", run.vars["out"])
		}
	})
	t.Run("xml2js", func(t *testing.T) {
		run := &scriptRun{vars: map[string]string{}}
		err := runScript(`
const xml2js = require("xml2js");
const parts = ["<root>"];
for (let i = 0; i < 500; i++) parts.push("<item id='" + i + "'>value</item>");
parts.push("</root>");
let parsed;
xml2js.parseString(parts.join(""), { explicitArray: false }, (err, result) => { parsed = result; });
// Internal entity declarations are not expanded by sax; the parse either
// errors or keeps the literal text, and never multiplies the input.
let bomb = "<!DOCTYPE lolz [<!ENTITY lol 'lol'>]><lolz>&lol;&lol;&lol;</lolz>";
let bombResult = "error";
xml2js.parseString(bomb, { explicitArray: false }, (err, result) => { if (!err) bombResult = JSON.stringify(result).length; });
pm.environment.set("out", JSON.stringify({ items: parsed.root.item.length, bomb: bombResult }));`, run, nil)
		if err != nil {
			t.Fatal(err)
		}
		var got struct {
			Items int `json:"items"`
			Bomb  any `json:"bomb"`
		}
		if err := json.Unmarshal([]byte(run.vars["out"]), &got); err != nil {
			t.Fatal(err)
		}
		if got.Items != 500 {
			t.Errorf("items = %d, want 500", got.Items)
		}
		if n, ok := got.Bomb.(float64); ok && n > 1000 {
			t.Errorf("entity input expanded to %v bytes; sax must not expand DTD entities", got.Bomb)
		}
	})
	t.Run("csv-parse", func(t *testing.T) {
		run := &scriptRun{vars: map[string]string{}}
		err := runScript(`
const parse = require("csv-parse/lib/sync");
const parts = ["a,b,c"];
for (let i = 0; i < 500; i++) parts.push(i + ",x,y");
const rows = parse(parts.join("\n"), { columns: true });
pm.environment.set("out", String(rows.length));`, run, nil)
		if err != nil {
			t.Fatal(err)
		}
		if run.vars["out"] != "500" {
			t.Errorf("rows = %s, want 500", run.vars["out"])
		}
	})
}

// TestSandboxRequireIsPerScript checks the two caching rules: one require per
// script returns the same exports, and the next script gets a fresh copy.
func TestSandboxRequireIsPerScript(t *testing.T) {
	first := &scriptRun{vars: map[string]string{}}
	if err := runScript(`const a = require("cheerio"); a.marker = "set"; pm.environment.set("same", String(a === require("cheerio"))); pm.environment.set("marker", a.marker);`, first, nil); err != nil {
		t.Fatal(err)
	}
	if first.vars["same"] != "true" || first.vars["marker"] != "set" {
		t.Fatalf("same script: same=%q marker=%q", first.vars["same"], first.vars["marker"])
	}
	second := &scriptRun{vars: map[string]string{}}
	if err := runScript(`pm.environment.set("marker", String(require("cheerio").marker));`, second, nil); err != nil {
		t.Fatal(err)
	}
	if second.vars["marker"] != "undefined" {
		t.Errorf("next script saw marker %q; exports must be fresh", second.vars["marker"])
	}
}

// TestSandboxAddonImportsLibraries checks that the ES module path rule
// scripts, addons and Code Mocks use can import the new modules too.
func TestSandboxAddonImportsLibraries(t *testing.T) {
	run := &scriptRun{vars: map[string]string{}, addons: map[string]string{
		"html": `import cheerio from "cheerio";
export function title(html) { return cheerio.load(html)("title").text(); }`,
	}}
	if err := runScript(`pm.environment.set("out", require("html").title("<title>Addon</title>"));`, run, nil); err != nil {
		t.Fatal(err)
	}
	if run.vars["out"] != "Addon" {
		t.Fatalf("out = %q", run.vars["out"])
	}
}

// TestSandboxUnknownModule names the modules require does not have.
func TestSandboxUnknownModule(t *testing.T) {
	run := &scriptRun{vars: map[string]string{}}
	err := runScript(`require("left-pad")`, run, nil)
	if err == nil || !strings.Contains(err.Error(), "not available") {
		t.Fatalf("err = %v", err)
	}
}
